COMMENT ON COLUMN "AIR_CARRIERS".CODE IS 'the code of the air carriers';
COMMENT ON COLUMN "AIR_CARRIERS".DESCRIPTION IS 'the description of air carriers';
COMMENT ON COLUMN AIRLINES.FL_DATE IS 'flight date';
COMMENT ON COLUMN AIRLINES.OP_CARRIER_AIRLINE_ID IS 'operator carrier airline id';
COMMENT ON COLUMN AIRLINES.TAIL_NUM IS 'plane''s tail number';
ALTER TABLE AIRLINES MODIFY (TAIL_NUM ANNOTATIONS (ADD value_description 'plane''s tail number'));
COMMENT ON COLUMN AIRLINES.OP_CARRIER_FL_NUM IS 'operator carrier flight number';
COMMENT ON COLUMN AIRLINES.ORIGIN_AIRPORT_ID IS 'origin airport id';
COMMENT ON COLUMN AIRLINES.ORIGIN_AIRPORT_SEQ_ID IS 'origin airport sequence id';
COMMENT ON COLUMN AIRLINES.ORIGIN_CITY_MARKET_ID IS 'origin city market id';
COMMENT ON COLUMN AIRLINES.ORIGIN IS 'airport of origin';
ALTER TABLE AIRLINES MODIFY (ORIGIN ANNOTATIONS (ADD value_description 'commonsense evidence:• the origin city could be inferred by this code:you can refer to https://www.iata.org/en/publications/directories/code-search/?airport.search=miato quickly check'));
COMMENT ON COLUMN AIRLINES.DEST_AIRPORT_ID IS 'ID of the destination airport';
COMMENT ON COLUMN AIRLINES.DEST IS 'Destination airport';
ALTER TABLE AIRLINES MODIFY (DEST ANNOTATIONS (ADD value_description 'commonsense evidence:• the dest city could be inferred by this code:you can refer to https://www.iata.org/en/publications/directories/code-search/?airport.search=miato quickly check'));
COMMENT ON COLUMN AIRLINES.DEP_TIME IS 'Flight departure time';
ALTER TABLE AIRLINES MODIFY (DEP_TIME ANNOTATIONS (ADD value_description 'stored as the integer'));
COMMENT ON COLUMN AIRLINES.DEP_DELAY IS 'Departure delay indicator';
ALTER TABLE AIRLINES MODIFY (DEP_DELAY ANNOTATIONS (ADD value_description 'in minutescommonsense evidence:• if this value is positive: it means this flight delays; if the value is negative, it means this flight departs in advance (-4)• if this value <= 0, it means this flight departs on time'));
COMMENT ON COLUMN AIRLINES.DEP_DELAY_NEW IS 'departure delay new';
ALTER TABLE AIRLINES MODIFY (DEP_DELAY_NEW ANNOTATIONS (ADD value_description 'not useful'));
COMMENT ON COLUMN AIRLINES.ARR_TIME IS 'Flight arrival time.';
COMMENT ON COLUMN AIRLINES.ARR_DELAY IS 'arrival delay time';
ALTER TABLE AIRLINES MODIFY (ARR_DELAY ANNOTATIONS (ADD value_description 'in minutescommonsense evidence:• if this value is positive: it means this flight will arrives late (delay); If the value is negative, this flight arrives earlier than scheduled. (-4)• if this value <= 0, it means this flight arrives on time'));
COMMENT ON COLUMN AIRLINES.ARR_DELAY_NEW IS 'arrival delay new';
ALTER TABLE AIRLINES MODIFY (ARR_DELAY_NEW ANNOTATIONS (ADD value_description 'not useful'));
COMMENT ON COLUMN AIRLINES.CANCELLED IS 'Flight cancellation indicator.';
COMMENT ON COLUMN AIRLINES.CANCELLATION_CODE IS 'cancellation code';
ALTER TABLE AIRLINES MODIFY (CANCELLATION_CODE ANNOTATIONS (ADD value_description 'commonsense evidence:C--> A: more serious reasons lead to this cancellation'));
COMMENT ON COLUMN AIRLINES.CRS_ELAPSED_TIME IS 'scheduled elapsed time';
COMMENT ON COLUMN AIRLINES.ACTUAL_ELAPSED_TIME IS 'actual elapsed time';
ALTER TABLE AIRLINES MODIFY (ACTUAL_ELAPSED_TIME ANNOTATIONS (ADD value_description 'commonsense evidence:if ACTUAL_ELAPSED_TIME < CRS_ELAPSED_TIME: this flight is faster than scheduled;if ACTUAL_ELAPSED_TIME > CRS_ELAPSED_TIME: this flight is slower than scheduled'));
COMMENT ON COLUMN AIRLINES.CARRIER_DELAY IS 'carrier delay';
ALTER TABLE AIRLINES MODIFY (CARRIER_DELAY ANNOTATIONS (ADD value_description 'minutes'));
COMMENT ON COLUMN AIRLINES.WEATHER_DELAY IS 'delay caused by the wheather problem';
ALTER TABLE AIRLINES MODIFY (WEATHER_DELAY ANNOTATIONS (ADD value_description 'minutes'));
COMMENT ON COLUMN AIRLINES.NAS_DELAY IS 'delay, in minutes, attributable to the National Aviation System';
ALTER TABLE AIRLINES MODIFY (NAS_DELAY ANNOTATIONS (ADD value_description 'minutes'));
COMMENT ON COLUMN AIRLINES.SECURITY_DELAY IS 'delay attribute to security';
ALTER TABLE AIRLINES MODIFY (SECURITY_DELAY ANNOTATIONS (ADD value_description 'minutes'));
COMMENT ON COLUMN AIRLINES.LATE_AIRCRAFT_DELAY IS 'delay attribute to late aircraft';
ALTER TABLE AIRLINES MODIFY (LATE_AIRCRAFT_DELAY ANNOTATIONS (ADD value_description 'minutes'));
COMMENT ON COLUMN AIRPORTS.CODE IS 'IATA code of the air airports';
COMMENT ON COLUMN AIRPORTS.DESCRIPTION IS 'the description of airports';